B.aaZ=new A.bM("p01","\u0627\u0644\u063a\u0627\u0641","Ghaf tree","Prosopis cineraria",B.d3,B.aj,B.ak,B.ax,10,!1,"\u0634\u062c\u0631\u0629 \u0645\u062d\u0644\u064a\u0629 \u062f\u0627\u0626\u0645\u0629 \u0627\u0644\u062e\u0636\u0631\u0629 \u062a\u062a\u062d\u0645\u0644 \u0627\u0644\u062d\u0631 \u0648\u0627\u0644\u062c\u0641\u0627\u0641\u060c \u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0644\u0638\u0644 \u0641\u064a \u0627\u0644\u062d\u062f\u0627\u0626\u0642 \u0648\u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062d\u0627\u062a.","Native evergreen that tolerates heat and drought; good shade tree for gardens.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null)
B.aaX=new A.bM("p02","\u0627\u0644\u0633\u0645\u0631","Umbrella thorn acacia","Vachellia tortilis",B.d3,B.aj,B.ak,B.ax,14,!1,"\u0634\u062c\u0631\u0629 \u0635\u062d\u0631\u0627\u0648\u064a\u0629 \u0645\u0638\u0644\u064a\u0629 \u0627\u0644\u0634\u0643\u0644\u060c \u062a\u062d\u062a\u0627\u062c \u0645\u0627\u0621\u064b \u0642\u0644\u064a\u0644\u0627\u064b \u062c\u062f\u0627\u064b \u0628\u0639\u062f \u0623\u0646 \u062a\u062b\u0628\u062a.","Umbrella-shaped desert tree; needs very little water once established.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null)
